Table.Command:
DO BEGIN
DECLARE fromDate DATETIME = {?$[BOY_AB_FROMDATE]};
DECLARE toDate DATETIME = {?$[BOY_AB_TODATE]};
DECLARE fromDateDue DATETIME = {?$[BOY_AB_DUE_FROMDATE]};
DECLARE toDateDue DATETIME = {?$[BOY_AB_DUE_TODATE]};
DECLARE fromDateDoc DATETIME = {?$[BOY_AB_DOC_FROMDATE]};
DECLARE toDateDoc DATETIME = {?$[BOY_AB_DOC_TODATE]};
DECLARE cardCode NVARCHAR(15) = '{?CardCode}';
DECLARE branch INTEGER = {?$[BOY_AB_BRANCH]};
IF ('{?$[BOY_AB_INCLUDE_RT]}' = 'N') THEN 
	WITH DATA AS
	(
		(
			SELECT 0 AS "Debit", MAX(T0."BalDueCred") + SUM(T1."ReconSum") AS "Credit", 0 AS "FcDebit", IFNULL(MAX(T0."BalFcCred"),0) + IFNULL(SUM(T1."ReconSumFC"),0) AS "FcCredit" FROM "JDT1" T0 
			INNER JOIN "ITR1" T1 ON T1."TransId" = T0."TransId" AND T1."TransRowId" = T0."Line_ID" 
			INNER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
			INNER JOIN "OCRD" T4 ON T4."CardCode" = T0."ShortName" WHERE 1 = 1 AND CASE WHEN branch = -1 THEN -1 ELSE T0."BPLId" END = branch AND T0."RefDate" < fromDate AND T4."CardCode" = cardCode AND T2."ReconDate" > toDate AND T1."IsCredit" = 'C' 
			GROUP BY T0."TransId", T0."Line_ID", T0."BPLName" 
			HAVING MAX(T0."BalFcCred") <> -SUM(T1."ReconSumFC") OR MAX(T0."BalDueCred") <> -SUM(T1."ReconSum") 

			UNION ALL 

			SELECT MAX(T0."BalDueDeb") + SUM(T1."ReconSum"), 0, IFNULL(MAX(T0."BalFcDeb"),0) + IFNULL(SUM(T1."ReconSumFC"),0), 0 FROM "JDT1" T0 
			INNER JOIN "ITR1" T1 ON T1."TransId" = T0."TransId" AND T1."TransRowId" = T0."Line_ID" 
			INNER JOIN "OITR" T2 ON T2."ReconNum" = T1."ReconNum" 
			INNER JOIN "OCRD" T4 ON T4."CardCode" = T0."ShortName" WHERE 1 = 1 AND CASE WHEN branch = -1 THEN -1 ELSE T0."BPLId" END = branch AND T0."RefDate" < fromDate AND T4."CardCode" = CardCode AND T2."ReconDate" > toDate AND T1."IsCredit" = 'D' 
			GROUP BY T0."TransId", T0."Line_ID", T0."BPLName" 
			HAVING MAX(T0."BalFcDeb") <> -SUM(T1."ReconSumFC") OR MAX(T0."BalDueDeb") <> -SUM(T1."ReconSum")
		)  	

		UNION ALL 

		SELECT MAX(T0."BalDueDeb"), MAX(T0."BalDueCred"), MAX(T0."BalFcDeb"), MAX(T0."BalFcCred") FROM "JDT1" T0 
		INNER JOIN "OJDT" T1 ON T1."TransId" = T0."TransId" 
		INNER JOIN "OCRD" T2 ON T2."CardCode" = T0."ShortName" WHERE 1 = 1 AND 
		CASE WHEN branch = -1 THEN -1 ELSE T0."BPLId" END = branch AND T0."RefDate" < fromDate AND T2."CardCode" = CardCode AND (T0."BalDueCred" <> T0."BalDueDeb" OR T0."BalFcCred" <> T0."BalFcDeb") 
		AND NOT EXISTS 
		(
			SELECT U0."TransId", U0."TransRowId" FROM "ITR1" U0 
			INNER JOIN "OITR" U1 ON U1."ReconNum" = U0."ReconNum" WHERE T0."TransId" = U0."TransId" AND T0."Line_ID" = U0."TransRowId" AND U1."ReconDate" > toDate 
			GROUP BY U0."TransId", U0."TransRowId"
		) 
		GROUP BY T0."TransId", T0."Line_ID", T0."BPLName"
	)
	SELECT IFNULL(SUM(T0."Debit" - T0."Credit"), 0) AS "Primo", IFNULL(SUM(T0."FcDebit" - T0."FcCredit"), 0) AS "PrimoFc" FROM "DATA" T0;
ELSE 
	SELECT IFNULL(SUM(T0."Debit" - T0."Credit"), 0) AS "Primo", IFNULL(SUM(T0."FCDebit" - T0."FCCredit"), 0) AS "PrimoFc" FROM "JDT1" T0 WHERE T0."ShortName" = cardCode AND 
	CASE WHEN branch = -1 THEN -1 ELSE T0."BPLId" END = branch AND T0."RefDate" < 
	(
		SELECT MIN(T0."RefDate") FROM "JDT1" T0 WHERE T0."ShortName" = cardCode AND T0."RefDate" BETWEEN fromDate AND toDate 
		AND T0."DueDate" BETWEEN fromDateDue AND toDateDue   AND T0."TaxDate" BETWEEN fromDateDoc AND toDateDoc  
	); 
END IF;
END;
